import * as THREE from 'three/webgpu';
import { texture, uv, mix, vec2, vec3, float, fract, sin, dot } from 'three/tsl';

export default function createNode(config, ctx) {
  const position = config.scenePosition || [0, -0.3, 0];
  const rotation = config.sceneRotation || [0, 0, 0];
  const scale = config.sceneScale || [1, 1, 1];

  const group = new THREE.Group();
  group.position.set(position[0], position[1], position[2]);
  group.rotation.set(rotation[0], rotation[1], rotation[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  // Design tokens
  const ink = vec3(0.086, 0.086, 0.114);      // #16161d
  const surface = vec3(0.043, 0.043, 0.063);  // #0b0b10
  const paper = vec3(0.910, 0.925, 0.949);    // #e8ecf2

  // Cached texture (synchronous)
  const tex = ctx.textureLoader(config.imageUrl);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.wrapS = THREE.ClampToEdgeWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;

  // Atlas region (0,0,512,320) → aspect 1.6
  const rect = config.atlasRect || { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h;
  const planeW = 1.6;
  const planeH = planeW / aspect;
  const geometry = new THREE.PlaneGeometry(planeW, planeH, 1, 1);

  // Atlas UV transform: map full-image UV into source rect
  // (rect starts at 0,0 so identity when image == rect size)
  const img = tex.image;
  const texW = (img && img.width) ? img.width : rect.w;
  const texH = (img && img.height) ? img.height : rect.h;
  const rectX = rect.x || 0;
  const rectY = rect.y || 0;
  const repX = rect.w / texW;
  const repY = rect.h / texH;
  const offX = rectX / texW;
  const offY = 1.0 - (rectY / texH) - repY; // flip Y for top-left origin
  const atlasUV = uv().mul(vec2(float(repX), float(repY))).add(vec2(float(offX), float(offY)));

  // Texture sample
  const texSample = texture(tex, atlasUV);

  // Engineered gradient surface: ink (top) -> surface (bottom), machined depth
  const gradT = uv().y;
  const gradientColor = mix(ink.mul(0.7), surface, gradT);
  // Blend texture with engineered gradient (texture remains dominant)
  const baseColor = mix(texSample.rgb, gradientColor, float(0.18));

  // Subtle vertical highlight band (machined-metal sheen, no pastel blur)
  const sheen = uv().y.sub(float(0.32)).abs().oneMinus().max(float(0.0)).pow(float(3.0));
  const sheenColor = paper.mul(0.06);
  const withSheen = baseColor.add(sheenColor.mul(sheen));

  // Subtle grain
  const grain = fract(sin(dot(uv().mul(float(850.0)), vec2(12.9898, 78.233))).mul(float(43758.5453)));
  const grainAmount = grain.sub(float(0.5)).mul(float(0.03));
  const finalColor = withSheen.add(vec3(grainAmount));

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = finalColor;
  material.transparent = true;
  material.side = THREE.DoubleSide;
  material.depthWrite = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.renderOrder = 1;
  group.add(mesh);

  // Apply cinematic primitives (none specified for this node)
  const primitives = config.cinematicPrimitives || [];
  for (const prim of primitives) {
    if (ctx.primitives && ctx.primitives[prim.name]) {
      ctx.primitives[prim.name](mesh, prim.params || {});
    }
  }

  // No interactions — static composition
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Cached texture owned by loader — do not dispose
  };

  return group;
}
